ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    success: false,
    error: {
        code: "BAD_REQUEST",
        message: error.description default "Invalid request payload or malformed syntax.",
        details: error.detailedDescription default "Validation constraint failed against RAML contract."
    },
    timestamp: (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"},
    correlationId: vars.correlationId default uuid()
}

%dw 2.0
output application/json
---
{
    success: false,
    error: {
        code: "UNAUTHORIZED",
        message: error.description default "Missing or invalid carrier authentication credentials.",
        details: "Provide valid X-Carrier-Token header corresponding to configured carrier shared secret."
    },
    timestamp: (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"},
    correlationId: vars.correlationId default uuid()
}

%dw 2.0
output application/json
---
{
